use super::common::{Gpu, captured, forget, from_bf16, replay, to_bf16};
use dtype::Dtype;
use kernels_cuda::{Tensor, linear::flashinfer};

#[test]
#[ignore = "requires the optional FlashInfer bridge and prewarmed cubins"]
fn the_flashinfer_fp8_body_preserves_windows() {
    const H: usize = 2560;
    const I: usize = 640;
    const E: usize = 16;
    const TOP: usize = 10;
    assert!(flashinfer::enabled());
    // Independently generated by FlashInfer Python 0.7.0.post1, same sparse matrices.
    #[allow(clippy::excessive_precision)] // Exact BF16 values exported by the independent reference.
    const GOLDEN: [[f32; 8]; 8] = [
        [
            0.005859375,
            0.0152587890625,
            0.0234375,
            0.042236328125,
            0.06591796875,
            0.0093994140625,
            0.0234375,
            0.03759765625,
        ],
        [
            0.006103515625,
            0.015869140625,
            0.0244140625,
            0.044189453125,
            0.06884765625,
            0.00982666015625,
            0.0244140625,
            0.039306640625,
        ],
        [
            0.006011962890625,
            0.015625,
            0.0240478515625,
            0.043212890625,
            0.0673828125,
            0.0096435546875,
            0.0240478515625,
            0.03857421875,
        ],
        [
            0.005767822265625,
            0.0150146484375,
            0.0230712890625,
            0.04150390625,
            0.06494140625,
            0.00927734375,
            0.0230712890625,
            0.037109375,
        ],
        [
            0.006500244140625,
            0.016845703125,
            0.0260009765625,
            0.046875,
            0.07275390625,
            0.01043701171875,
            0.0260009765625,
            0.041748046875,
        ],
        [
            0.00628662109375,
            0.016357421875,
            0.025146484375,
            0.04541015625,
            0.07080078125,
            0.0101318359375,
            0.025146484375,
            0.04052734375,
        ],
        [
            0.006072998046875,
            0.015869140625,
            0.0242919921875,
            0.043701171875,
            0.068359375,
            0.009765625,
            0.0242919921875,
            0.0390625,
        ],
        [
            0.006072998046875,
            0.015869140625,
            0.0242919921875,
            0.043701171875,
            0.068359375,
            0.009765625,
            0.0242919921875,
            0.0390625,
        ],
    ];
    for rows in [1usize, 4, 128] {
        let mut gpu = Gpu::open();
        let ctx = gpu.ctx();
        let x: Vec<_> = (0..(rows + 2) * H)
            .map(|i| to_bf16(((i % H) % 8 + 1) as f32 / 8.))
            .collect();
        // Sparse, non-symmetric gate/up matrices make swapped halves observable.
        let mut up = vec![0u8; E * 2 * I * H];
        let mut down = vec![0u8; E * H * I];
        for e in 0..E {
            for j in 0..I {
                up[(e * 2 * I + j) * H + j] = 0x38;
                up[(e * 2 * I + I + j) * H + (j + 3) % H] = 0x40;
            }
            for j in 0..H {
                down[(e * H + j) * I + j % I] = 0x38;
            }
        }
        let us: Vec<_> = (0..E * 2 * (I / 128) * (H / 128))
            .map(|i| {
                if (i / (I / 128 * (H / 128))).is_multiple_of(2) {
                    0.5f32
                } else {
                    0.25
                }
            })
            .collect();
        let ds: Vec<_> = (0..E * (H / 128) * (I / 128))
            .map(|i| 0.5f32 + 0.25 * (i / ((H / 128) * (I / 128)) % 3) as f32)
            .collect();
        let up = Tensor::new(gpu.up(&up), E as u32, (2 * I * H) as u32, Dtype::E4m3);
        let us = Tensor::new(
            gpu.up(&us),
            E as u32,
            (2 * (I / 128) * (H / 128) * 4) as u32,
            Dtype::U8,
        );
        let down = Tensor::new(gpu.up(&down), E as u32, (H * I) as u32, Dtype::E4m3);
        let ds_t = Tensor::new(
            gpu.up(&ds),
            E as u32,
            ((H / 128) * (I / 128) * 4) as u32,
            Dtype::U8,
        );
        flashinfer::swap_gate_up(&ctx, up, us).unwrap();
        let ids: Vec<i32> = (0..(rows + 2) * TOP).map(|i| (i % E) as i32).collect();
        let probs: Vec<f32> = (0..(rows + 2) * TOP)
            .map(|i| (i % TOP + 1) as f32 / 55.)
            .collect();
        let a = Tensor::new(gpu.up(&x), rows as u32, H as u32, Dtype::Bf16);
        let ids_t = Tensor::new(gpu.up(&ids), rows as u32, TOP as u32, Dtype::I32);
        let probs_t = Tensor::new(gpu.up(&probs), rows as u32, TOP as u32, Dtype::F32);
        let sentinel = to_bf16(-99.);
        let mut y = Tensor::new(
            gpu.up(&vec![sentinel; (rows + 2) * H]),
            rows as u32,
            H as u32,
            Dtype::Bf16,
        );
        let win = gpu.up(&[rows as u32, 1u32]);
        ctx.arm_stage(win);
        flashinfer::experts(
            &ctx, a, up, us, down, ds_t, ids_t, probs_t, I as u32, &mut y,
        )
        .unwrap();
        let graph = captured(&ctx, || {
            flashinfer::experts(
                &ctx, a, up, us, down, ds_t, ids_t, probs_t, I as u32, &mut y,
            )
            .unwrap()
        });
        replay(&ctx, graph);
        gpu.sync();
        let got: Vec<u16> = gpu.down(y.ptr, (rows + 2) * H);
        assert!(
            got[..H]
                .iter()
                .chain(&got[(rows + 1) * H..])
                .all(|v| *v == sentinel)
        );
        for r in 1..=rows {
            for c in 0..H {
                let j = c % I;
                let gate = from_bf16(x[r * H + j]) * 0.5;
                let up = from_bf16(x[r * H + (j + 3) % H]) * 0.5;
                let hidden = gate / (1. + (-gate).exp()) * up;
                let want: f32 = (0..TOP)
                    .map(|t| {
                        let e = ids[r * TOP + t] as usize;
                        hidden * ds[e * (H / 128) * (I / 128)] * probs[r * TOP + t]
                    })
                    .sum();
                let value = from_bf16(got[r * H + c]);
                assert_eq!(value, GOLDEN[(r - 1) % 8][c % 8]);
                assert!(
                    (value - want).abs() < 0.15 * want.abs().max(0.001),
                    "{r},{c}: {value} vs {want}"
                );
            }
        }
        // Change the same device window between replays, including an empty fire.
        unsafe {
            let window = [0u32, 1];
            let rt = kernels_cuda::cudarc::runtime::sys::cudaMemcpy(
                win as *mut _,
                window.as_ptr().cast(),
                8,
                kernels_cuda::cudarc::runtime::sys::cudaMemcpyKind::cudaMemcpyHostToDevice,
            );
            assert_eq!(
                rt,
                kernels_cuda::cudarc::runtime::sys::cudaError::cudaSuccess
            );
        }
        replay(&ctx, graph);
        gpu.sync();
        assert_eq!(gpu.down::<u16>(y.ptr, (rows + 2) * H), got);
        forget(graph);
    }
}
